macro_rules! deps {
    () => {
        PackageFile!();
        PackageIdSpec!();
    };
}

macro_rules! PackageList {
    () => {
        deps!();
        # [doc = " File information of a package archive generated by `cargo package --list`."] # [derive (Debug , serde :: Serialize)] # [serde (rename_all = "snake_case")] pub struct PackageList { # [doc = " The Package ID Spec of the package."] pub id : crate :: core :: PackageIdSpec , # [doc = " A map of relative paths in the archive to their detailed file information."] pub files : BTreeMap < PathBuf , PackageFile > , }
    };
}

PackageList!()